"""native/apiref.py: every snippet the API reference puts at the cursor has to compile in an effect file - the
reference offered sin8, beatsin8, random8 and inoise8, which this WLED tree no longer declares (sin8_t, beatsin8_t,
hw_random8, perlin8). Each snippet goes into its own block of one function in a file shaped like the new-effect
template, and the file is compiled with -fsyntax-only against the engine's includes. Needs a C++ compiler; skipped
without one. Run with  python tests/test_apiref.py  (or pytest)."""
# AI: below section was generated by an AI
import os
import sys
import tempfile

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from native import procs, toolchain  # noqa: E402
from native.apiref import API  # noqa: E402
import build as B  # noqa: E402

# The names the snippets lean on, declared once so each snippet compiles as it is pasted.
PRELUDE = r'''#include "wled.h"
#include "cube_fx_common.h"
#include "cube_fx_bank.h"

static FX_RET mode_my_effect() { FX_DONE; }
static const char _data_FX_MODE_MY_EFFECT[] PROGMEM = "My effect@;;!;12";
uint32_t cfxPaletteSourceColor(uint8_t pos, uint8_t bri) __attribute__((weak));   // as the reference says: declare it weak

static FX_RET apiref_snippets() {
  int x = 1, y = 2, i = 0, W = 8, H = 8, cols = 48, rows = 48, B = 16;
  bool cube = false;
  uint8_t idx = 0, hue = 0, a = 0, b = 0, v = 0, s = 0, r = 0, g = 0;
  uint32_t c = 0, t = 0, z = 0;
  const size_t N = 16;
  CfxTumble tum;
  um_data_t *um = cfx_getAudioData();
  uint8_t *fft = (uint8_t*)um->u_data[2];
  uint16_t step = 1;
  CfxTempoState &tempo = cfx_tempo(um);
  (void)x; (void)y; (void)i; (void)W; (void)H; (void)cols; (void)rows; (void)B; (void)cube;
  (void)idx; (void)hue; (void)a; (void)b; (void)v; (void)s; (void)r; (void)g; (void)c; (void)t; (void)fft; (void)step; (void)z; (void)N; (void)tempo;
'''


def _block(snippet):
    """One snippet as a self-contained block: a statement as written, an expression cast to void, and any braces
    the snippet leaves open (an `if (...) {`, the net loop) closed."""
    body = snippet.strip()
    if not body.endswith((";", "{", "}")):
        body = "(void)(%s);" % body
    return "  {\n    %s\n  %s}\n" % (body.replace("\n", "\n    "), "}" * (body.count("{") - body.count("}")))


def _source():
    out = [PRELUDE]
    for group, rows in API:
        for label, snippet, _ in rows:
            if group == "metadata" and snippet.startswith('"'):
                out.append("  { static const char m[] = %s; (void)m; }\n" % snippet)
            elif snippet.startswith("static CfxBankReg"):
                continue                                    # a file-scope line: placed after the function
            else:
                out.append("  // %s\n%s" % (label, _block(snippet)))
    out.append("}\n")
    out += [snippet + "\n" for _, rows in API for _, snippet, _ in rows if snippet.startswith("static CfxBankReg")]
    return "".join(out)


def test_every_snippet_compiles():
    try:
        cc, env = toolchain.find_compiler()
    except toolchain.ToolchainError as ex:
        print("skipped: no compiler -", ex)
        return
    d = tempfile.mkdtemp(prefix="apiref_")
    src = os.path.join(d, "apiref_snippets.cpp")
    with open(src, "w", encoding="utf-8") as f:
        f.write(_source())
    cmd = [cc] + toolchain._tu_flags(cc) + ["-fsyntax-only"] + toolchain._inc_flags(B.include_dirs()) + [src]
    r = procs.run(cmd, capture_output=True, text=True, env=env, cwd=toolchain.HERE)
    errs = [ln for ln in ((r.stdout or "") + (r.stderr or "")).splitlines() if "error" in ln]
    assert r.returncode == 0, "snippets that do not compile:\n" + "\n".join(errs[:20])


if __name__ == "__main__":
    try:
        test_every_snippet_compiles(); print("ok   test_every_snippet_compiles")
    except AssertionError as ex:
        print("FAIL test_every_snippet_compiles -", ex); sys.exit(1)
